import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../application/itqan_journey_provider.dart';
import '../../quran_journey/presentation/quran_journey_screen.dart';
import '../../adhkar_journey/presentation/adhkar_journey_screen.dart';
import '../../dua_journey/presentation/dua_journey_screen.dart';
import '../../share_journey/presentation/share_journey_screen.dart';

class JourneyDashboardScreen extends ConsumerStatefulWidget{const JourneyDashboardScreen({super.key});@override ConsumerState<JourneyDashboardScreen> createState()=>_JourneyDashboardScreenState();}
class _JourneyDashboardScreenState extends ConsumerState<JourneyDashboardScreen>{@override void initState(){super.initState();Future.microtask(()=>ref.read(itqanJourneyProvider.notifier).loadAll());}
@override Widget build(BuildContext context){final s=ref.watch(itqanJourneyProvider);return Scaffold(appBar:AppBar(title:const Text('رحلتك إلى الأفضل')),body:s.loading&&s.profile==null?const Center(child:CircularProgressIndicator()):s.error!=null&&s.profile==null?Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text(s.error!),TextButton(onPressed:()=>ref.read(itqanJourneyProvider.notifier).loadAll(),child:const Text('إعادة المحاولة'))])):RefreshIndicator(onRefresh:()=>ref.read(itqanJourneyProvider.notifier).loadAll(),child:ListView(padding:const EdgeInsets.all(16),children:[_profile(s.profile),const SizedBox(height:12),..._modules(context),const SizedBox(height:12),if(s.tasks!=null)Text('المهام المكتملة: ${s.tasks!['counts']?['completed']??0} / ${s.tasks!['counts']?['total']??0}'),if(s.streak!=null)Text('الاستمرارية الحالية: ${s.streak!['current_streak']??0}'),const SizedBox(height:16),OutlinedButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>const JourneyAchievementsScreen())),icon:const Icon(Icons.military_tech),label:const Text('الإنجازات والأوسمة')),OutlinedButton.icon(onPressed:()=>Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>const JourneyLeaderboardScreen())),icon:const Icon(Icons.leaderboard),label:const Text('العشرة الأوائل'))])));}
Widget _profile(Map<String,dynamic>? data){final stats=data?['stats'] as Map?;final level=stats?['level'] as Map?;final tasks=stats?['tasks'] as Map?;final ratio=(((level?['progress_percentage'] as num?)?.toDouble()??0)/100).clamp(0.0,1.0);return Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('رحلتك إلى الأفضل',style:Theme.of(context).textTheme.titleLarge),Text('المستوى ${level?['number']??'—'} • ${level?['title']??''}'),Text('${stats?['total_xp']??0} XP'),const SizedBox(height:8),LinearProgressIndicator(value:ratio),const SizedBox(height:8),Text('المهام المكتملة: ${tasks?['completed_total']??0} / ${tasks?['total_available']??0}')])));}
List<Widget> _modules(BuildContext context)=>[('القرآن الكريم','اقرأ وردك اليومي',Icons.menu_book_rounded,const QuranJourneyScreen()),('الأذكار','حافظ على أذكارك اليومية',Icons.spa_rounded,const AdhkarJourneyScreen()),('الأدعية','اقرأ دعاء اليوم',Icons.volunteer_activism_rounded,const DuaJourneyScreen()),('مشاركة الخير','شارك فائدة أو ذكراً أو دعاءً',Icons.share_rounded,const ShareJourneyScreen())].map((e)=>Card(child:ListTile(leading:Icon(e.$3,color:Theme.of(context).colorScheme.primary),title:Text(e.$1),subtitle:Text(e.$2),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(context,MaterialPageRoute<void>(builder:(_)=>e.$4))))).toList();}

class JourneyAchievementsScreen extends ConsumerWidget{const JourneyAchievementsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final s=ref.watch(itqanJourneyProvider);final list=(s.achievements?['achievements'] as List?)??const [];final earned=list.where((e)=>e is Map&&e['is_earned']==true).toList();return Scaffold(appBar:AppBar(title:const Text('الإنجازات والأوسمة')),body:s.achievements==null?Center(child:Text(s.error??'جارٍ تحميل الإنجازات')):earned.isEmpty?const Center(child:Text('لم تحصل على أوسمة بعد')):ListView(children:earned.map((e){final a=Map<String,dynamic>.from(e as Map);return ListTile(leading:const Icon(Icons.military_tech),title:Text('${a['title']??''}'),subtitle:Text('${a['description']??''}\n${a['earned_at']??''}'));}).toList()));}}
class JourneyLeaderboardScreen extends ConsumerStatefulWidget{const JourneyLeaderboardScreen({super.key});@override ConsumerState<JourneyLeaderboardScreen> createState()=>_JourneyLeaderboardScreenState();}
class _JourneyLeaderboardScreenState extends ConsumerState<JourneyLeaderboardScreen>{@override void initState(){super.initState();Future.microtask(()=>ref.read(itqanJourneyProvider.notifier).refreshLeaderboard());}@override Widget build(BuildContext context){final s=ref.watch(itqanJourneyProvider);final data=s.leaderboard;final top=(data?['top'] as List?)??const [];final me=data?['me'] as Map?;return Scaffold(appBar:AppBar(title:const Text('العشرة الأوائل')),body:RefreshIndicator(onRefresh:()=>ref.read(itqanJourneyProvider.notifier).refreshLeaderboard(),child:data==null?ListView(children:[const SizedBox(height:160),Center(child:Text(s.error??'جارٍ التحميل'))]):ListView(padding:const EdgeInsets.all(16),children:[Text('أكثر المستخدمين إنجازاً'),const Text('ترتيب كلي (كل الأوقات)'),if(top.isEmpty)const Padding(padding:EdgeInsets.all(24),child:Text('لا توجد نتائج')),for(final row in top)ListTile(leading:CircleAvatar(child:Text('${row['rank']}')),title:Text('${row['name']}'),subtitle:Text('المستوى ${row['level']} • ${row['level_title']}'),trailing:Text('${row['score']} XP')),if(me?['rank']==null)const Card(child:ListTile(title:Text('لم تسجل نشاطاً بعد'))),if(me?['rank']!=null&&me?['in_top']!=true)Card(child:ListTile(title:Text('مركزك الحالي: ${me?['rank']}'),trailing:Text('${me?['score']} XP')))])));}}
